"""Admin-only reset of call history and records generated by calls."""

import logging
from datetime import datetime
from typing import Any, Dict

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

from auth_service import require_permission, verify_password
from mongo_client import mongo_client
from routers.inbox_api import _thread_key

logger = logging.getLogger(__name__)
router = APIRouter(prefix="/api/platform/data-reset", tags=["data reset"])

AUTO_VOICE_LEADS = {
    "source": {"$in": ["voice", "retell"]},
    "notes": "Automatically captured from an inbound voice call.",
}
LABELS = {
    "calls": "Call history, transcripts, analysis, and recording links",
    "ai_activity": "Voice AI activity",
    "inbox_threads": "Call inbox state",
    "notifications": "Call notifications",
    "team_messages": "Notes attached to call threads",
    "leads": "Automatically created voice leads",
}


class ResetRequest(BaseModel):
    confirmation: str
    password: str


def _require_safe_admin(user: Dict[str, Any]) -> None:
    if user.get("role") not in {"owner", "admin"}:
        raise HTTPException(status_code=403, detail="Only an admin can clear call data")
    if not mongo_client.is_connected():
        raise HTTPException(status_code=503, detail="Database is not connected")
    workspaces = set(mongo_client.users.distinct("workspace_id"))
    if workspaces != {user.get("workspace_id", "default")}:
        raise HTTPException(status_code=409, detail="Call reset is unavailable while multiple workspaces share this database")


def _queries() -> Dict[str, Dict[str, Any]]:
    calls = list(mongo_client.calls.find({}, {"_id": 1, "phone_number": 1, "call_session_id": 1}))
    thread_keys = list({_thread_key(call) for call in calls})
    threads = {"$in": thread_keys} if thread_keys else {"$in": []}
    return {
        "calls": {},
        "ai_activity": {"channel": "voice"},
        "inbox_threads": {"_id": threads},
        "notifications": {"$or": [{"channel": "voice"}, {"conversation_id": threads}]},
        "team_messages": {"conversation_id": threads},
        "leads": AUTO_VOICE_LEADS,
    }


@router.get("/preview")
def preview_data_reset(user: Dict[str, Any] = Depends(require_permission("manage_workspace"))):
    _require_safe_admin(user)
    queries = _queries()
    counts = {name: mongo_client.db[name].count_documents(query) for name, query in queries.items()}
    return {"success": True, "data": {"counts": counts, "labels": LABELS, "total": sum(counts.values())}}


@router.post("")
def reset_data(payload: ResetRequest, user: Dict[str, Any] = Depends(require_permission("manage_workspace"))):
    _require_safe_admin(user)
    if payload.confirmation != "CLEAR CALL DATA":
        raise HTTPException(status_code=400, detail="Type CLEAR CALL DATA to confirm")
    if not verify_password(payload.password, user.get("password_hash", "")):
        raise HTTPException(status_code=403, detail="Current password is incorrect")

    queries = _queries()
    deleted: Dict[str, int] = {}
    try:
        # Resolve thread keys before removing calls, then delete dependent records first.
        for name in ("ai_activity", "inbox_threads", "notifications", "team_messages", "leads", "calls"):
            deleted[name] = mongo_client.db[name].delete_many(queries[name]).deleted_count
        mongo_client.audit_logs.insert_one({
            "actor": str(user.get("_id")), "action": "call_data_reset", "resource": "calls",
            "after": {"deleted": deleted}, "created_at": datetime.utcnow(),
        })
    except Exception:
        logger.exception("call data reset failed after deleting %s", deleted)
        raise HTTPException(status_code=500, detail="Call data reset stopped before completion; check the server log")
    logger.warning("call data reset by %s: deleted=%s", user.get("_id"), deleted)
    return {"success": True, "data": {"deleted": deleted}}
